import React, { useEffect, useState } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import axios from "axios";
import toast from "react-hot-toast";

const UpdateUser = () => {
  const [user, setUser] = useState({
    name: "",
    class1: "",
    roll: "",
  });

  const navigate = useNavigate();
  const { id } = useParams();

  const inputHandler = (e) => {
    const { name, value } = e.target;
    setUser({ ...user, [name]: value });
  };

  useEffect(() => {
    axios
      .get(`http://localhost:8005/api/user/${id}`) // ✅ Correct port
      .then((response) => {
        console.log("Fetched user:", response.data);
        setUser(response.data); // ✅ or response.data.data if your backend wraps it
      })
      .catch((error) => {
        console.log("Error fetching user:", error);
      });
  }, [id]);

  const submitForm = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.put(
        `http://localhost:8005/api/update/user/${id}`,
        user
      );
      toast.success(response.data.message, { position: "top-right" });
      navigate("/Teacherdashboard"); // optional redirect
    } catch (error) {
      console.log(error);
      toast.error("Failed to update student", { position: "top-right" });
    }
  };

  return (
    <div className="addUser">
      <Link to="/Teacherdashboard" type="button" className="btn btn-secondary">
        <i className="fa-solid fa-backward"></i> Back
      </Link>

      <h3>Update Student</h3>
      <form className="addUserForm" onSubmit={submitForm}>
        <div className="inputGroup">
          <label htmlFor="name">Name:</label>
          <input
            type="text"
            id="name"
            value={user.name}
            onChange={inputHandler}
            name="name"
            autoComplete="off"
            placeholder="Enter your Name"
          />
        </div>

        <div className="inputGroup">
          <label htmlFor="class1">Class:</label>
          <select
            name="class1"
            value={user.class1}
            onChange={inputHandler}
          >
            <option value="">-- Select a Class --</option>
            <option value="10">10</option>
            <option value="9">9</option>
            <option value="8">8</option>
            <option value="7">7</option>
          </select>
        </div>

        <div className="inputGroup">
          <label htmlFor="roll">Roll No:</label>
          <input
            type="text"
            id="roll"
            value={user.roll}
            name="roll"
            autoComplete="off"
            placeholder="Enter roll number"
            onChange={inputHandler}
          />
        </div>

        <div className="inputGroup">
          <button type="submit" className="btn btn-primary">
            Update
          </button>
        </div>
      </form>
    </div>
  );
};

export default UpdateUser;
